"""Forvynx portable checker v0.1.0; copied verbatim, never generated by an LLM.

This quality gate validates a repository snapshot, not human authorization.
"""

import argparse
import hashlib
import json
import os
import stat
import subprocess
import sys
import tempfile
import time
from pathlib import Path, PurePosixPath

BEGIN = "<!-- forvynx:begin -->"
END = "<!-- forvynx:end -->"
LIMIT = 2 * 1024 * 1024


def safe_relative(name):
    if not isinstance(name, str) or not name or "\\" in name or ":" in name or "\x00" in name:
        raise ValueError("Unsafe relative path")
    parts = name.split("/")
    if PurePosixPath(name).is_absolute() or any(p in ("", ".", "..", ".git") for p in parts):
        raise ValueError("Unsafe relative path")
    return name


def git_read(root, *args, index_file=None):
    env = {k: v for k, v in os.environ.items() if not k.startswith("GIT_")}
    env.update(GIT_OPTIONAL_LOCKS="0", GIT_TERMINAL_PROMPT="0", LC_ALL="C")
    if index_file:
        env["GIT_INDEX_FILE"] = index_file
    result = subprocess.run(["git", "-c", "core.fsmonitor=false", "-C", str(root), *args],
                            env=env, stdout=subprocess.PIPE, stderr=subprocess.PIPE, timeout=15)
    if result.returncode:
        raise ValueError("Git snapshot read failed")
    return result.stdout


class Snapshot:
    def __init__(self, root, source):
        self.root = Path(root).resolve()
        self.source = source
        self.index = {}
        if source == "index":
            active_index = os.environ.get("GIT_INDEX_FILE")
            active_index = str(Path(active_index).absolute()) if active_index else None
            for entry in git_read(self.root, "ls-files", "--stage", "-z", index_file=active_index).split(b"\x00"):
                if not entry:
                    continue
                meta, name = entry.split(b"\t", 1)
                mode, oid, stage = meta.split()
                if stage != b"0":
                    raise ValueError("Unresolved multi-stage index")
                self.index[name.decode("utf-8")] = (mode, oid)

    def read(self, name):
        safe_relative(name)
        if self.source == "index":
            mode, oid = self.index.get(name, (None, None))
            if mode not in (b"100644", b"100755"):
                raise ValueError(f"Missing or non-regular indexed file: {name}")
            data = git_read(self.root, "cat-file", "blob", oid.decode("ascii"))
        else:
            path = self.root.joinpath(*name.split("/"))
            for item in (path, *path.parents):
                if item == self.root:
                    break
                try:
                    info = item.lstat()
                except FileNotFoundError as exc:
                    raise ValueError(f"Missing file: {name}") from exc
                if stat.S_ISLNK(info.st_mode) or getattr(info, "st_file_attributes", 0) & 0x400:
                    raise ValueError(f"Linked path: {name}")
            if not path.is_file() or path.stat().st_size > LIMIT:
                raise ValueError(f"Not a bounded regular file: {name}")
            data = path.read_bytes()
        if len(data) > LIMIT:
            raise ValueError("Snapshot file too large")
        return data


def validate_config(config):
    if config.get("schema_version") != 1 or config.get("generator") != "forvynx":
        raise ValueError("Unsupported repository config")
    if config.get("profile") not in ("generic", "python"):
        raise ValueError("Unsupported profile")
    if not isinstance(config.get("ci"), bool):
        raise ValueError("CI generation flag must be a boolean")
    if not isinstance(config.get("components"), dict) or not isinstance(config.get("checks"), list):
        raise ValueError("Missing components/checks")
    for required in (".forvynx/check.py", ".forvynx/workflow.md"):
        if required not in config["components"]:
            raise ValueError(f"Missing component: {required}")
    seen = set()
    for check in config["checks"]:
        check_id = check.get("id")
        if not isinstance(check_id, str) or not check_id or check_id in seen:
            raise ValueError("Duplicate/invalid check ID")
        seen.add(check_id)
        if not isinstance(check.get("required"), bool):
            raise ValueError("Check must declare required")
        argv = check.get("argv")
        if not isinstance(argv, list) or not argv or any(not isinstance(a, str) or "\x00" in a for a in argv) or not argv[0]:
            raise ValueError("Check argv must be a nonempty string array")
        cwd = check.get("cwd", ".")
        if cwd != ".":
            safe_relative(cwd)
        if not isinstance(check.get("timeout"), (int, float)) or not 0 < check["timeout"] <= 600:
            raise ValueError("Check timeout must be in (0, 600]")
        if not isinstance(check.get("env"), dict) or any(not isinstance(k, str) or not isinstance(v, str) or "=" in k or "\x00" in k + v for k, v in check["env"].items()):
            raise ValueError("Invalid check environment")
        if not isinstance(check.get("sources", []), list):
            raise ValueError("Check sources must be a list")
        for source in check.get("sources", []):
            safe_relative(source)
    return config


def inspect_snapshot(snapshot):
    config = validate_config(json.loads(snapshot.read(".forvynx/repo.json")))
    for name, expected in config["components"].items():
        if hashlib.sha256(snapshot.read(name)).hexdigest() != expected:
            raise ValueError(f"Component drift: {name}")
    agents = snapshot.read("AGENTS.md").decode("utf-8")
    if agents.count(BEGIN) != 1 or agents.count(END) != 1 or agents.index(BEGIN) >= agents.index(END):
        raise ValueError("Invalid managed AGENTS block")
    if ".forvynx/workflow.md" not in agents.split(BEGIN)[1].split(END)[0]:
        raise ValueError("Missing workflow reference")
    for check in config["checks"]:
        for source in check.get("sources", []):
            snapshot.read(source)
    return config


def run_check(root, check):
    root = Path(root).resolve()
    cwd = root if check["cwd"] == "." else root.joinpath(*safe_relative(check["cwd"]).split("/"))
    if not cwd.is_dir():
        return {"id": check["id"], "required": check["required"], "status": "unsupported", "exit_code": None, "reason": "cwd unavailable"}
    for part in (cwd, *cwd.parents):
        if part == root:
            break
        info = part.lstat()
        if stat.S_ISLNK(info.st_mode) or getattr(info, "st_file_attributes", 0) & 0x400:
            raise ValueError("Linked check working directory")
    cwd.resolve().relative_to(root)
    argv = [sys.executable if arg == "$PYTHON" else arg for arg in check["argv"]]
    env = os.environ.copy()
    env.update(check["env"])
    env["PYTHONDONTWRITEBYTECODE"] = "1"
    started = time.monotonic()
    result = {"id": check["id"], "required": check["required"], "argv": argv, "cwd": str(cwd), "output": "not_recorded"}
    try:
        # Discard output instead of retaining secrets or an unbounded output file.
        with open(os.devnull, "wb") as output:
            proc = subprocess.Popen(argv, cwd=cwd, env=env, stdout=output, stderr=output, shell=False)
            try:
                result["exit_code"] = proc.wait(timeout=check["timeout"])
                result["status"] = "passed" if result["exit_code"] == 0 else "failed"
            except subprocess.TimeoutExpired:
                proc.kill()
                proc.wait()
                result.update(status="failed", exit_code=None, reason="timeout; spawned child processes may require host cleanup")
    except FileNotFoundError:
        result.update(status="unsupported", exit_code=None, reason="executable or cwd unavailable")
    result["duration_ms"] = round((time.monotonic() - started) * 1000)
    return result


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--root", default=".")
    parser.add_argument("--source", choices=("worktree", "index"), default="worktree")
    parser.add_argument("--execute", action="store_true", help="Execute configured checks; repository code runs")
    args = parser.parse_args()
    try:
        if args.source == "index" and args.execute:
            raise ValueError("Index mode only permits structural checks")
        config = inspect_snapshot(Snapshot(args.root, args.source))
        checks = [run_check(args.root, c) if args.execute else {"id": c["id"], "required": c["required"], "status": "not_run"} for c in config["checks"]]
        ready = all(not c["required"] or c["status"] == "passed" for c in checks)
        # Structural hook intentionally does not claim engineering checks passed.
        structural = args.source == "index"
        print(json.dumps({"structure": "passed", "checks": checks, "ready": ready, "gate": "structural" if structural else "engineering",
                          "engineering_verification": "configured" if checks else "not_configured"}))
        if structural or ready:
            return 0
        return 4 if any(c["status"] == "failed" and c["required"] for c in checks) else 2
    except (ValueError, KeyError, TypeError, OSError, subprocess.SubprocessError) as exc:
        print(json.dumps({"structure": "failed", "ready": False, "reason": str(exc)}))
        return 4


if __name__ == "__main__":
    sys.exit(main())
